// Package proposals contains the fail-closed proposal-target contract.
package proposals

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"unicode"
)

// Proposal is the target portion of an emit_proposal request.
//
// The validator intentionally does not know about queue rows or apply-side
// consent. It only checks the structural target and computes mkdirs.
type Proposal struct {
	Path      string
	Operation string
	Content   string
}

// ValidationResult contains derived data for a valid proposal.
// Mkdirs is ordered shallowest first and is never created by validation.
type ValidationResult struct {
	Mkdirs []string
}

// ValidateProposalTarget applies R1-R3, the C4 stub tripwire, and mkdirs
// computation. It performs no writes.
func ValidateProposalTarget(proposal Proposal) (ValidationResult, error) {
	path := strings.TrimSpace(proposal.Path)
	op := proposal.Operation
	if op == "" {
		op = "replace"
	}

	if path == "" {
		return ValidationResult{}, fmt.Errorf(
			"[manage] emit_proposal needs a path: re-emit with the absolute path (starting with /)",
		)
	}
	if !filepath.IsAbs(path) {
		return ValidationResult{}, fmt.Errorf(
			"[manage] emit_proposal requires an ABSOLUTE path (got %q): relative paths are rejected because the apply side may resolve them against the wrong root; re-emit with the full absolute path",
			path,
		)
	}

	// C4 stub tripwire: message-boundary markers are not payloads.
	if strings.HasPrefix(strings.TrimLeftFunc(proposal.Content, unicode.IsSpace), "[evicted:") {
		return ValidationResult{}, fmt.Errorf(
			"[manage] proposal content for %s looks like a C4 eviction stub, not a payload (it starts with %[1]q); re-read the real file or re-compose the payload, then re-emit with the actual content",
			"[evicted:",
		)
	}

	exists := pathExists(path)
	if op == "create" {
		if exists {
			return ValidationResult{}, fmt.Errorf(
				"[manage] emit_proposal (create) target already exists: %s; use replace or edit_range for an existing file, then re-emit",
				path,
			)
		}
		return ValidationResult{Mkdirs: missingParentDirs(path)}, nil
	}

	if !exists {
		return ValidationResult{}, fmt.Errorf(
			"[manage] emit_proposal (%s) requires the target to exist: %s; update operations never create files, so verify the path or re-emit as create",
			op,
		path,
		)
	}
	return ValidationResult{Mkdirs: []string{}}, nil
}

func pathExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func isDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

// missingParentDirs returns the absent directory chain above target's parent,
// shallowest first. The root directory is never returned.
func missingParentDirs(target string) []string {
	missing := []string{}
	dir := filepath.Dir(target)
	for {
		parent := filepath.Dir(dir)
		if dir == parent || isDir(dir) {
			break
		}
		missing = append([]string{dir}, missing...)
		dir = parent
	}
	return missing
}

