package proposals

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Row is one queued proposal line. Mkdirs is omitted (absent key) unless it
// is non-empty, matching the TS row shape: `mkdirs` appears ONLY on create
// rows with a missing parent chain.
type Row struct {
	Path      string   `json:"path"`
	Operation string   `json:"operation,omitempty"`
	Content   string   `json:"content"`
	Mkdirs    []string `json:"mkdirs,omitempty"`
}

// ProposalsFile returns <directory>/.ai-proposals/<sessionID>.jsonl.
func ProposalsFile(directory, sessionID string) string {
	return filepath.Join(directory, ".ai-proposals", sessionID+".jsonl")
}

// AppendProposal validates the target FIRST (an invalid target writes
// NOTHING to the queue), then appends one JSON row per line. It returns the
// computed mkdirs so the caller can name missing directories up front.
func AppendProposal(directory, sessionID string, proposal Proposal) (Row, error) {
	result, err := ValidateProposalTarget(proposal)
	if err != nil {
		return Row{}, err
	}

	file := ProposalsFile(directory, sessionID)
	if err := os.MkdirAll(filepath.Dir(file), 0o755); err != nil {
		return Row{}, fmt.Errorf("[manage] could not create the proposals queue directory: %w", err)
	}

	row := Row{
		Path:      strings.TrimSpace(proposal.Path),
		Operation: proposal.Operation,
		Content:   proposal.Content,
	}
	if row.Operation == "" {
		row.Operation = "replace"
	}
	if row.Operation == "create" {
		row.Mkdirs = result.Mkdirs
	}

	data, err := json.Marshal(row)
	if err != nil {
		return Row{}, fmt.Errorf("[manage] could not encode the proposal row: %w", err)
	}
	f, err := os.OpenFile(file, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return Row{}, fmt.Errorf("[manage] could not open the proposals queue file: %w", err)
	}
	defer f.Close()
	if _, err := f.Write(append(data, '\n')); err != nil {
		return Row{}, fmt.Errorf("[manage] could not append the proposal row: %w", err)
	}
	return row, nil
}

