package proposals

import (
	"bufio"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func readRows(t *testing.T, file string) []map[string]any {
	t.Helper()
	f, err := os.Open(file)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	rows := []map[string]any{}
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}
		var row map[string]any
		if err := json.Unmarshal([]byte(line), &row); err != nil {
			t.Fatalf("bad JSONL line %q: %v", line, err)
		}
		rows = append(rows, row)
	}
	return rows
}

func TestProposalsFilePath(t *testing.T) {
	got := ProposalsFile("/proj", "ses_1")
	want := filepath.Join("/proj", ".ai-proposals", "ses_1.jsonl")
	if got != want {
		t.Fatalf("ProposalsFile = %q, want %q", got, want)
	}
}

func TestAppendProposalParity(t *testing.T) {
	root := t.TempDir()
	existing := filepath.Join(root, "existing.md")
	if err := os.WriteFile(existing, []byte("x\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	t.Run("valid create appends row with mkdirs", func(t *testing.T) {
		file := ProposalsFile(root, "ses_a")
		row, err := AppendProposal(root, "ses_a", Proposal{
			Path:      filepath.Join(root, "new", "nested", "f.md"),
			Operation: "create",
			Content:   "payload",
		})
		if err != nil {
			t.Fatal(err)
		}
		if len(row.Mkdirs) != 2 {
			t.Fatalf("mkdirs = %v, want 2 entries", row.Mkdirs)
		}
		rows := readRows(t, file)
		if len(rows) != 1 {
			t.Fatalf("wrote %d rows, want 1", len(rows))
		}
		if _, ok := rows[0]["mkdirs"]; !ok {
			t.Fatal("create row must carry mkdirs")
		}
	})

	t.Run("replace row omits mkdirs key", func(t *testing.T) {
		file := ProposalsFile(root, "ses_b")
		if _, err := AppendProposal(root, "ses_b", Proposal{
			Path:      existing,
			Operation: "replace",
			Content:   "updated",
		}); err != nil {
			t.Fatal(err)
		}
		rows := readRows(t, file)
		if len(rows) != 1 {
			t.Fatalf("wrote %d rows, want 1", len(rows))
		}
		if _, ok := rows[0]["mkdirs"]; ok {
			t.Fatal("non-create row must omit mkdirs")
		}
	})

	t.Run("invalid target writes nothing", func(t *testing.T) {
		file := ProposalsFile(root, "ses_c")
		if _, err := AppendProposal(root, "ses_c", Proposal{
			Path:      filepath.Join(root, "missing.md"),
			Operation: "replace",
			Content:   "x",
		}); err == nil {
			t.Fatal("expected R2 error")
		}
		if _, statErr := os.Stat(file); !os.IsNotExist(statErr) {
			t.Fatal("invalid proposal must not create or touch the queue file")
		}
	})

	t.Run("stub content writes nothing", func(t *testing.T) {
		file := ProposalsFile(root, "ses_d")
		_, err := AppendProposal(root, "ses_d", Proposal{
			Path:      filepath.Join(root, "stub.md"),
			Operation: "create",
			Content:   "\n[evicted: probe]",
		})
		if err == nil || !strings.Contains(err.Error(), "C4 eviction stub") {
			t.Fatalf("expected C4 stub error, got %v", err)
		}
		if _, statErr := os.Stat(file); !os.IsNotExist(statErr) {
			t.Fatal("stub proposal must not create the queue file")
		}
	})

	t.Run("empty operation defaults to replace in row", func(t *testing.T) {
		file := ProposalsFile(root, "ses_e")
		row, err := AppendProposal(root, "ses_e", Proposal{
			Path:    existing,
			Content: "x",
		})
		if err != nil {
			t.Fatal(err)
		}
		if row.Operation != "replace" {
			t.Fatalf("operation = %q, want replace", row.Operation)
		}
		rows := readRows(t, file)
		if rows[len(rows)-1]["operation"] != "replace" {
			t.Fatal("row must record the defaulted operation")
		}
	})
}

