package proposals

// M4 cross-language parity: run the shared fixture (parity/cases.json)
// through the Go validator. The TS side (plugins/lib/proposals.selftest.ts)
// runs the SAME fixture through validateProposalTarget; both must agree.

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

type parityExpect struct {
	ErrorContains string   `json:"error_contains"`
	OK            bool     `json:"ok"`
	Mkdirs        []string `json:"mkdirs"`
}

type parityCase struct {
	Name      string      `json:"name"`
	Operation string      `json:"operation"`
	Path      string      `json:"path"`
	Content   string      `json:"content"`
	Expect    parityExpect `json:"expect"`
}

type parityFixture struct {
	Comment string       `json:"comment"`
	Cases   []parityCase `json:"cases"`
}

func loadParityFixture(t *testing.T) ([]parityCase, string) {
	t.Helper()
	file := filepath.Join("..", "..", "parity", "cases.json")
	data, err := os.ReadFile(file)
	if err != nil {
		t.Fatalf("parity fixture unreadable: %v", err)
	}
	var fixture parityFixture
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatalf("parity fixture malformed: %v", err)
	}
	if len(fixture.Cases) == 0 {
		t.Fatal("parity fixture has no cases")
	}
	return fixture.Cases, filepath.Dir(file)
}

func TestParityWithTSValidator(t *testing.T) {
	cases, _ := loadParityFixture(t)

	root := t.TempDir()
	existing := filepath.Join(root, "existing.md")
	if err := os.WriteFile(existing, []byte("seed\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	resolve := func(s string) string {
		return filepath.FromSlash(strings.ReplaceAll(s, "$ROOT", root))
	}

	for _, c := range cases {
		t.Run(c.Name, func(t *testing.T) {
			got, err := ValidateProposalTarget(Proposal{
				Path:      resolve(c.Path),
				Operation: c.Operation,
				Content:   c.Content,
			})

			if c.Expect.OK {
				if err != nil {
					t.Fatalf("expected pass, got error: %v", err)
				}
				want := []string{}
				for _, m := range c.Expect.Mkdirs {
					want = append(want, resolve(m))
				}
				if !reflect.DeepEqual(got.Mkdirs, want) {
					t.Fatalf("mkdirs = %v, want %v", got.Mkdirs, want)
				}
				return
			}

			if err == nil {
				t.Fatalf("expected failure containing %q, got pass", c.Expect.ErrorContains)
			}
			if !strings.Contains(err.Error(), c.Expect.ErrorContains) {
				t.Fatalf("error %q does not contain %q", err, c.Expect.ErrorContains)
			}
		})
	}
}

