/**
 * Daemon client (M6): HTTP over the manage unix socket.
 * - ensureDaemon: health-check, spawn-on-demand, bounded wait.
 * - shutdownDaemon: best-effort POST /shutdownz.
 * Fail-closed: if the daemon cannot be started or reached, callers throw —
 * the plugin never silently falls back to embedded logic.
 */
import { spawn } from "child_process";
import { request as httpRequest } from "http";
import { homedir } from "os";
import { join } from "path";

const SOCKET = join(
  homedir(),
  ".local",
  "share",
  "opencode-manage",
  "manage.sock",
);
const BIN =
  process.env.MANAGE_BIN ||
  join(homedir(), "projects", "opencode-manage", "bin", "manage");

export type DaemonResponse = { status: number; body: string };

export function daemonRequest(
  method: string,
  path: string,
  body?: string,
): Promise<DaemonResponse> {
  return new Promise((resolve, reject) => {
    const req = httpRequest(
      {
        socketPath: SOCKET,
        path,
        method,
        headers: body
          ? { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) }
          : undefined,
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on("data", (c: Buffer) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode ?? 0,
            body: Buffer.concat(chunks).toString("utf8"),
          }),
        );
      },
    );
    req.on("error", reject);
    if (body) req.write(body);
    req.end();
  });
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function ensureDaemon(): Promise<void> {
  try {
    await daemonRequest("GET", "/healthz");
    return;
  } catch {
    // not running — spawn below
  }
  spawn(BIN, [], { detached: true, stdio: "ignore" }).unref();
  for (let i = 0; i < 30; i++) {
    await sleep(100);
    try {
      await daemonRequest("GET", "/healthz");
      return;
    } catch {
      // keep waiting
    }
  }
  throw new Error(
    "[manage] ⚠️ manage daemon unreachable at " + SOCKET +
      " after spawning " + BIN +
      ". Build it first (cd ~/projects/opencode-manage && make build), then retry.",
  );
}

export async function shutdownDaemon(): Promise<boolean> {
  try {
    const res = await daemonRequest("POST", "/shutdownz");
    return res.status === 202;
  } catch {
    return false;
  }
}

