/**
 * Proposals pipeline (M6 thin client): validation and queueing now live in
 * the manage daemon (Go, sqlite-backed). This module keeps the public API
 * the tools already call — but every call goes over the daemon socket.
 * The daemon is the trusted writer: it inserts the sqlite row AND appends
 * the JSONL line the nvim review console reads. The AI still has no file
 * path. Fail-closed: an unreachable daemon throws.
 */
import { daemonRequest, ensureDaemon } from "./daemon";

export function proposalsFile(directory: string, sessionID: string): string {
  return `${directory}/.ai-proposals/${sessionID}.jsonl`;
}

export type ProposalTarget = {
  path?: string;
  operation?: string;
  content?: unknown;
};

export type AppendResult = { mkdirs: string[] };

async function errorFrom(res: { status: number; body: string }): Promise<never> {
  let msg = res.body;
  try {
    msg = JSON.parse(res.body).error ?? res.body;
  } catch {
    // keep raw body
  }
  throw new Error(msg);
}

export async function validateProposalTarget(
  proposal: ProposalTarget,
): Promise<{ mkdirs: string[] }> {
  await ensureDaemon();
  const res = await daemonRequest(
    "POST",
    "/v1/proposals/validate",
    JSON.stringify({
      path: proposal.path ?? "",
      operation: proposal.operation ?? "",
      content: proposal.content ?? "",
    }),
  );
  if (res.status !== 200) await errorFrom(res);
  const parsed = JSON.parse(res.body);
  return { mkdirs: parsed.mkdirs ?? [] };
}

export async function appendProposal(
  directory: string,
  sessionID: string,
  proposal: Record<string, unknown>,
): Promise<AppendResult> {
  await ensureDaemon();
  const res = await daemonRequest(
    "POST",
    "/v1/proposals",
    JSON.stringify({
      directory,
      session_id: sessionID,
      row: proposal,
    }),
  );
  if (res.status !== 200) await errorFrom(res);
  const parsed = JSON.parse(res.body);
  return { mkdirs: parsed.mkdirs ?? [] };
}

