// Command manage runs the opencode-manage daemon: a chi HTTP server on a
// unix socket. M6: sqlite-backed proposals handlers. M7: event recording.
// Autostart: the opencode plugin spawns this binary at init; the daemon
// self-exits after an idle period (MANAGE_IDLE_TIMEOUT minutes, default 30)
// so no manual cleanup is needed.
//
// Singleton rule: a starting instance first PROBES the socket. A live
// daemon answers /healthz and the new instance exits 0 ("already
// running"). Only an unresponsive stale socket file is removed.
package main

import (
	"context"
	"database/sql"
	"errors"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
