/**
 * emit_proposal — the only code write channel: structured proposal.
 * M6: validation and queueing delegate to the manage daemon (awaited).
 *
 * Eviction-loop fixes (doc 16):
 * - operation "hunks": emit-from-disk edit hunks. The model sends
 *   {base_sha256, hunks:[{start_line,end_line,replacement}]} as content;
 *   the PLUGIN reads the file from disk, verifies the base hash, applies
 *   the hunks, and queues the composed full file as a normal `replace`
 *   row — the review console sees unchanged semantics. The model is no
 *   longer the transport layer for large payloads.
 * - retry escalation: an identical refused payload emitted again gets a
 *   STOP message instead of letting the model loop.
 */
import { tool } from "@opencode-ai/plugin";
import { createHash } from "crypto";
import { readFileSync } from "fs";
import {
  proposalsFile,
  appendProposal,
  validateProposalTarget,
} from "../proposals";
import { recordEvent } from "../metrics";
import {
