/**
 * proposal_status — read-only feedback channel (doc 16 follow-up).
 *
 * The emitting session previously had no way to learn whether its queued
 * proposals were applied: emit_proposal returns only a proposal_id, so a
 * session that ASSUMED acceptance misdiagnosed a build failure while the
 * real hunks sat pending (volleyball-new, group henry-player-subject).
 *
 * This tool reads the project journal (.ai-proposals/*.jsonl) and returns
 * per-file status. Read-only; nothing executes; no schema change — a row
 * without a status field reports "pending".
 */
import { tool } from "@opencode-ai/plugin";
import { readdirSync, readFileSync } from "fs";
import { join } from "path";

type JournalRow = {
  ts?: number | string;
  group?: string;
  path?: string;
  operation?: string;
  reason?: string;
  status?: string;
};

export function proposalStatusTool(directory: string) {
  return tool({
    description:
      "Read-only proposal status lookup. Returns pending/accepted/rejected " +
      "per file for your queued proposals, filtered by group, proposal id, " +
      "or path. Use this BEFORE diagnosing build failures in code you " +
      "proposed: a pending proposal means the change is NOT on disk yet. " +
      "Reads the project journal only; nothing is written or applied.",
    args: {
      group: tool.schema
        .string()
        .describe("Filter by group slug (e.g. 'henry-player-subject'). Empty = all groups."),
      proposal_id: tool.schema
        .string()
        .describe("Filter by proposal id (the ts returned by emit_proposal). Empty = all."),
      path: tool.schema
        .string()
        .describe("Filter by path substring. Empty = all."),
    },
    async execute(args: any, context: any) {
      const rows: Array<Record<string, unknown>> = [];
      const dir = join(directory, ".ai-proposals");
      let files: string[] = [];
      try {
        files = readdirSync(dir).filter((f) => f.endsWith(".jsonl"));
      } catch {
        return JSON.stringify(
          { ok: true, count: 0, proposals: [], note: "no journal yet — nothing queued" },
          null,
          2,
        );
      }
      for (const f of files) {
        let raw = "";
        try {
          raw = readFileSync(join(dir, f), "utf8");
        } catch {
          continue;
        }
        for (const line of raw.split("\n")) {
          if (!line.trim()) continue;
          let row: JournalRow;
          try {
            row = JSON.parse(line) as JournalRow;
          } catch {
            continue;
          }
          if (args.group && row.group !== args.group) continue;
          if (
            args.proposal_id &&
            String(row.ts ?? "") !== String(args.proposal_id)
          ) {
            continue;
          }
          if (args.path && !(row.path ?? "").includes(args.path)) continue;
          rows.push({
            proposal_id: row.ts ?? null,
            session: f.replace(/\.jsonl$/, ""),
            group: row.group ?? null,
            path: row.path ?? null,
            operation: row.operation ?? null,
            status: row.status ?? "pending",
            reason: row.reason ?? null,
          });
        }
      }
      rows.sort((a, b) => String(b.proposal_id).localeCompare(String(a.proposal_id)));
      const pending = rows.filter((r) => r.status === "pending").length;
      await recordEventSafe(directory, context?.sessionID, rows.length, pending);
      return JSON.stringify(
        {
          ok: true,
          count: rows.length,
          pending,
          proposals: rows.slice(0, 50),
          note:
            pending > 0
              ? `${pending} proposal(s) are PENDING — those changes are NOT on disk. Do not diagnose build failures against them; ask the user to review, or check again after they apply.`
              : "no pending proposals in this filter",
        },
        null,
        2,
      );
    },
  });
}

async function recordEventSafe(
  directory: string,
  sessionID: string | undefined,
  count: number,
  pending: number,
): Promise<void> {
  try {
    const { recordEvent } = await import("../metrics");
    await recordEvent(
      directory,
      sessionID,
      "proposal_status",
      `${count} row(s), ${pending} pending`,
      null,
    );
  } catch {
    // metrics are diagnostics, never a gate
  }
}

